        const sqlite3 = await import("@vscode/sqlite3");
        legacyDatabase = await new Promise((resolve, reject) => {
          const opened = new sqlite3.default.Database(path, (error) => error ? reject(error) : resolve(opened));
        });
        await new Promise((resolve, reject) => legacyDatabase.exec(`
					CREATE TABLE sessions (
						session_uri TEXT PRIMARY KEY NOT NULL,
						provider TEXT NOT NULL,
						start_time INTEGER NOT NULL
					);
					CREATE TABLE metadata (
						key TEXT PRIMARY KEY NOT NULL,
						value TEXT NOT NULL
					);
					INSERT INTO sessions (session_uri, provider, start_time) VALUES ('copilot:/legacy-real-database', 'copilot', 1);
					PRAGMA user_version = 1;
				`, (error) => error ? reject(error) : resolve()));
        await new Promise((resolve, reject) => legacyDatabase.close((error) => error ? reject(error) : resolve()));
        legacyDatabase = void 0;
        database = new AgentHostDatabase(path);
        const svc = disposables.add(new AgentService(new NullLogService(), fileService, createSessionDataService(), { _serviceBrand: void 0 }, createNoopGitService(), void 0, void 0, void 0, void 0, void 0, void 0, void 0, void 0, database));
        const agent = disposables.add(new MockAgent("copilot"));
